'use client';

import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react';
import { AlertTriangle, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpDown, BadgeCheck, Box, CalendarClock, Check, CheckCircle2, CircleDollarSign, Clock3, FileText, Fuel, MapPin, Package, Plus, Printer, RefreshCw, Route, ShieldAlert, Truck, UserRound, Warehouse, X } from 'lucide-react';
import Navbar from '../../components/Navbar';
import { useAuth } from '../../components/AuthProvider';

type Row=Record<string,any>;
type Tab='trips'|'resources'|'incidents';
const tripStatuses:Record<string,string>={planned:'Planificado',in_route:'En ruta',closed:'Cerrado',cancelled:'Cancelado'};
const stopStatuses:Record<string,string>={planned:'Pendiente',arrived:'En destino',delivered:'Entregado',partial:'Entrega parcial',failed:'Fallida',rescheduled:'Reprogramada'};
const expenseNames:Record<string,string>={fuel:'Combustible',toll:'Peaje',parking:'Parqueo',per_diem:'Viáticos',other:'Otro'};
const incidentNames:Record<string,string>={delay:'Retraso',damage:'Daño',loss:'Pérdida',accident:'Accidente',theft:'Robo',vehicle:'Vehículo',customer:'Cliente',other:'Otro'};
const toIso=(value:string)=>value?new Date(value).toISOString():null;
const localInput=(value?:string)=>value?new Date(value).toISOString().slice(0,16):'';

export default function TmsPage(){
  const {token,user}=useAuth();
  const canManage=user?.role==='admin'||Boolean(user?.permissions?.includes('tms.manage'));
  const canDispatch=user?.role==='admin'||Boolean(user?.permissions?.includes('tms.dispatch'));
  const canDeliver=user?.role==='admin'||Boolean(user?.permissions?.includes('tms.delivery'));
  const canFinance=user?.role==='admin'||Boolean(user?.permissions?.includes('tms.finance'));
  const canIncidents=user?.role==='admin'||Boolean(user?.permissions?.includes('tms.incidents'));
  const [tab,setTab]=useState<Tab>('trips');const [context,setContext]=useState<Row>({carriers:[],vehicles:[],drivers:[],tariffs:[],orders:[],incidents:[]});const [trips,setTrips]=useState<Row[]>([]);const [activeTrip,setActiveTrip]=useState<Row|null>(null);
  const [showCreate,setShowCreate]=useState(false);const [showClose,setShowClose]=useState(false);const [filter,setFilter]=useState('all');const [search,setSearch]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const [carrierForm,setCarrierForm]=useState<Row>({name:'',carrier_type:'transport_company',tax_id:'',contact_name:'',phone:'',email:'',zones:''});
  const [vehicleForm,setVehicleForm]=useState<Row>({carrier_id:'',plate:'',vehicle_type:'camioneta',is_owned:false,capacity_kg:0,capacity_m3:0,capacity_packages:0,registration_expiry:'',insurance_expiry:''});
  const [driverForm,setDriverForm]=useState<Row>({carrier_id:'',full_name:'',identification_number:'',phone:'',license_number:'',license_type:'',license_expiry:''});
  const [tariffForm,setTariffForm]=useState<Row>({carrier_id:'',name:'',zone:'',base_amount:0,per_km:0,per_kg:0,per_m3:0,per_package:0,per_stop:0,minimum_amount:0});
  const [tripForm,setTripForm]=useState<Row>({carrier_id:'',vehicle_id:'',driver_id:'',tariff_id:'',route_name:'',zone:'',planned_departure:localInput(new Date(Date.now()+3600000).toISOString()),planned_return:'',planned_distance_km:0,planned_duration_minutes:0,estimated_cost:0,notes:''});
  const [orderIds,setOrderIds]=useState<string[]>([]);const [stopWindows,setStopWindows]=useState<Row>({});const [stopForms,setStopForms]=useState<Row>({});
  const [expenseForm,setExpenseForm]=useState<Row>({expense_type:'fuel',description:'',amount:'',receipt_reference:''});const [incidentForm,setIncidentForm]=useState<Row>({incident_type:'delay',severity:'medium',description:'',claim_reference:'',estimated_loss:0});
  const [closeForm,setCloseForm]=useState<Row>({invoiced_amount:'',invoice_reference:''});
  const request=useCallback(async(path:string,init?:RequestInit)=>{const response=await fetch(path,{...init,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',...(init?.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(Array.isArray(data.message)?data.message.join(', '):data.message||'No se pudo completar la operación.');return data;},[token]);
  const refresh=useCallback(async()=>{if(!token)return;setError('');try{const [data,rows]=await Promise.all([request('/api/tms/context'),request('/api/tms/trips')]);setContext(data);setTrips(rows);}catch(err){setError(err instanceof Error?err.message:'No se pudieron cargar los datos del TMS.');}},[request,token]);
  useEffect(()=>{void refresh();},[refresh]);
  const openTrip=async(id:string)=>{try{const trip=await request(`/api/tms/trips/${id}`);setActiveTrip(trip);setStopForms(Object.fromEntries(trip.stops.map((stop:Row)=>[stop.id,{status:'delivered',received_by:'',signature_reference:'',photo_reference:'',latitude:'',longitude:'',delivery_notes:'',failure_reason:'',rescheduled_for:'',scheduled_from:localInput(stop.scheduled_from),scheduled_to:localInput(stop.scheduled_to),items:Object.fromEntries(stop.items.map((item:Row)=>[item.fulfillment_item_id,'']))}])));}catch(err){setError(err instanceof Error?err.message:'No se pudo abrir el viaje.');}};
  const notify=(text:string)=>{setNotice(text);window.setTimeout(()=>setNotice(''),3600);};
  const apiAction=async(path:string,method='POST',body:Row={})=>{setBusy(true);setError('');try{const result=await request(path,{method,body:JSON.stringify(body)});notify(result.trip_number?`Viaje ${result.trip_number} creado.`:'Cambios guardados.');await refresh();if(activeTrip?.id)await openTrip(activeTrip.id);return result;}catch(err){setError(err instanceof Error?err.message:'No se pudo guardar la operación.');return null;}finally{setBusy(false);}};
  const toggleResource=(kind:'carriers'|'vehicles'|'drivers'|'tariffs',resource:Row)=>{const next=kind==='carriers'||kind==='tariffs'?{is_active:!resource.is_active}:{status:resource.status==='active'?'inactive':'active'};void apiAction(`/api/tms/${kind}/${resource.id}`,'PATCH',next);};
  const saveResource=async(e:FormEvent,path:string,form:Row,setForm:(value:Row)=>void,reset:Row)=>{e.preventDefault();const body={...form,zones:form.zones?String(form.zones).split(',').map((x:string)=>x.trim()).filter(Boolean):undefined};const result=await apiAction(path,'POST',body);if(result)setForm(reset);};
  const createTrip=async(e:FormEvent)=>{e.preventDefault();if(!orderIds.length){setError('Selecciona al menos un pedido para el viaje.');return;}const result=await apiAction('/api/tms/trips','POST',{...tripForm,planned_departure:toIso(tripForm.planned_departure),planned_return:toIso(tripForm.planned_return),planned_distance_km:Number(tripForm.planned_distance_km||0),planned_duration_minutes:Number(tripForm.planned_duration_minutes||0),estimated_cost:Number(tripForm.estimated_cost||0),order_ids:orderIds,stops:orderIds.map((id)=>({order_id:id,scheduled_from:toIso(stopWindows[id]?.from||''),scheduled_to:toIso(stopWindows[id]?.to||'')}))});if(result){setShowCreate(false);setOrderIds([]);setActiveTrip(null);setTab('trips');await openTrip(result.id);}};
  const depart=async()=>{if(!activeTrip)return;await apiAction(`/api/tms/trips/${activeTrip.id}/depart`,'POST',{});};
  const moveStop=async(stopId:string,direction:number)=>{if(!activeTrip)return;const sorted=[...activeTrip.stops].sort((a,b)=>a.sequence_number-b.sequence_number);const current=sorted.findIndex((stop)=>stop.id===stopId);const next=current+direction;if(next<0||next>=sorted.length)return;[sorted[current],sorted[next]]=[sorted[next],sorted[current]];const result=await apiAction(`/api/tms/trips/${activeTrip.id}/resequence`,'POST',{stop_ids:sorted.map((stop)=>stop.id)});if(result)await openTrip(activeTrip.id);};
  const saveWindow=async(stop:Row)=>{if(!activeTrip)return;const form=stopForms[stop.id]||{};await apiAction(`/api/tms/trips/${activeTrip.id}/stops/${stop.id}/window`,'PATCH',{scheduled_from:toIso(form.scheduled_from||''),scheduled_to:toIso(form.scheduled_to||'')});};
  const updateStop=async(e:FormEvent,stop:Row)=>{e.preventDefault();if(!activeTrip)return;const form=stopForms[stop.id]||{};const body={...form,latitude:form.latitude===''?null:Number(form.latitude),longitude:form.longitude===''?null:Number(form.longitude),rescheduled_for:toIso(form.rescheduled_for||''),items:stop.items.map((item:Row)=>({fulfillment_item_id:item.fulfillment_item_id,quantity:Number(form.items?.[item.fulfillment_item_id]||0)})).filter((item:Row)=>item.quantity>0)};const result=await apiAction(`/api/tms/trips/${activeTrip.id}/stops/${stop.id}/status`,'POST',body);if(result)await openTrip(activeTrip.id);};
  const addExpense=async(e:FormEvent)=>{e.preventDefault();if(!activeTrip)return;const result=await apiAction(`/api/tms/trips/${activeTrip.id}/expenses`,'POST',{...expenseForm,amount:Number(expenseForm.amount)});if(result)setExpenseForm({expense_type:'fuel',description:'',amount:'',receipt_reference:''});};
  const addIncident=async(e:FormEvent)=>{e.preventDefault();if(!activeTrip)return;const result=await apiAction(`/api/tms/trips/${activeTrip.id}/incidents`,'POST',{...incidentForm,estimated_loss:Number(incidentForm.estimated_loss||0)});if(result){setIncidentForm({incident_type:'delay',severity:'medium',description:'',claim_reference:'',estimated_loss:0});setTab('incidents');}};
  const closeTrip=async(e:FormEvent)=>{e.preventDefault();if(!activeTrip)return;const result=await apiAction(`/api/tms/trips/${activeTrip.id}/close`,'POST',{...closeForm,invoiced_amount:Number(closeForm.invoiced_amount||0)});if(result){setShowClose(false);setCloseForm({invoiced_amount:'',invoice_reference:''});notify(result.reconciliation_status==='variance'?'Viaje cerrado; la factura tiene una diferencia frente a la tarifa.':'Viaje cerrado y liquidado.');}};
  const resolveIncident=async(id:string,status:'resolved'|'claim')=>{const note=window.prompt(status==='claim'?'Referencia del reclamo:':'Nota de resolución:')||'';await apiAction(`/api/tms/incidents/${id}/resolve`,'PATCH',{status,notes:note});};
  const toggleOrder=(id:string,checked:boolean)=>setOrderIds((current)=>checked?[...current,id]:current.filter((x)=>x!==id));
  const selectedOrders=orderIds.map((id)=>context.orders.find((order:Row)=>order.id===id)).filter(Boolean);
  const filteredTrips=useMemo(()=>trips.filter((trip)=>{const matches=filter==='all'||trip.status===filter;const q=search.trim().toLowerCase();return matches&&(!q||`${trip.trip_number} ${trip.route_name} ${trip.zone} ${trip.carrier_name} ${trip.vehicle_plate} ${trip.driver_name}`.toLowerCase().includes(q));}),[trips,filter,search]);
  const selectedCarrier=context.carriers.find((carrier:Row)=>carrier.id===tripForm.carrier_id);
  const compatibleVehicles=context.vehicles.filter((vehicle:Row)=>vehicle.status==='active'&&(!vehicle.carrier_id||vehicle.carrier_id===tripForm.carrier_id));
  const compatibleDrivers=context.drivers.filter((driver:Row)=>driver.status==='active'&&(!driver.carrier_id||driver.carrier_id===tripForm.carrier_id));
  const estimatedWeight=selectedOrders.reduce((sum:number,order:Row)=>sum+Number(order.package_weight_kg||order.shipment_weight_kg||0),0);
  const estimatedVolume=selectedOrders.reduce((sum:number,order:Row)=>sum+Number(order.package_volume_m3||order.shipment_volume_m3||0),0);
  const estimatedPackages=selectedOrders.reduce((sum:number,order:Row)=>sum+Number(order.package_count||0),0);
  const chosenTariff=context.tariffs.find((tariff:Row)=>tariff.id===tripForm.tariff_id);
  const tariffEstimate=chosenTariff?Math.max(Number(chosenTariff.minimum_amount||0),Number(chosenTariff.base_amount||0)+Number(tripForm.planned_distance_km||0)*Number(chosenTariff.per_km||0)+estimatedWeight*Number(chosenTariff.per_kg||0)+estimatedVolume*Number(chosenTariff.per_m3||0)+estimatedPackages*Number(chosenTariff.per_package||0)+selectedOrders.length*Number(chosenTariff.per_stop||0)):null;
  const routeCounts={planned:trips.filter((trip)=>trip.status==='planned').length,onRoute:trips.filter((trip)=>trip.status==='in_route').length,deliveries:trips.reduce((sum:number,trip:Row)=>sum+Number(trip.completed_stops||0),0),incidents:context.incidents.filter((incident:Row)=>incident.status!=='resolved').length};
  const resetResourceTab=()=>{setError('');setNotice('');};
  const tabs:[Tab,string,any][]=[['trips','Viajes y rutas',Route],['resources','Transportistas y flota',Truck],['incidents','Incidentes',AlertTriangle]];

  return <div className="logistics-layout tms-page"><Navbar/><main className="logistics-content"><div className="container">
    <header className="tms-header"><div><p className="eyebrow">LOGÍSTICA · TRANSPORTE Y DISTRIBUCIÓN</p><h1>Centro de transporte</h1><p>Flota, rutas, entregas, POD, gastos y conciliación de transportistas.</p></div><div className="tms-header-actions"><button className="storage-icon-button" onClick={()=>void refresh()} aria-label="Actualizar TMS"><RefreshCw size={17}/></button>{canManage&&<button className="action-btn" onClick={()=>{resetResourceTab();setShowCreate(true);}}><Plus size={16}/> Planificar viaje</button>}</div></header>
    <section className="tms-kpis"><article><span>Viajes por salir</span><strong>{routeCounts.planned}</strong><small><CalendarClock size={13}/> Planificados</small></article><article><span>En ruta</span><strong>{routeCounts.onRoute}</strong><small><Truck size={13}/> Requieren seguimiento</small></article><article><span>Paradas resueltas</span><strong>{routeCounts.deliveries}</strong><small><BadgeCheck size={13}/> Entregas y novedades</small></article><article><span>Incidentes abiertos</span><strong>{routeCounts.incidents}</strong><small><ShieldAlert size={13}/> Pendientes de atención</small></article></section>
    {error&&<div className="storage-alert error" role="alert">{error}<button onClick={()=>setError('')}>Cerrar</button></div>}{notice&&<div className="storage-alert success"><Check size={16}/>{notice}</div>}
    <nav className="storage-tabs tms-tabs" aria-label="Áreas del TMS">{tabs.map(([id,label,Icon])=><button key={id} type="button" className={tab===id?'active':''} onClick={()=>setTab(id)}><Icon size={16}/>{label}{id==='incidents'&&routeCounts.incidents>0&&<span>{routeCounts.incidents}</span>}</button>)}</nav>

    {tab==='trips'&&<section className="storage-panel"><div className="storage-panel-heading"><div><h2><Route size={20}/> Viajes, manifiestos y planificación</h2><p>Las entregas se asignan a pedidos ya despachados desde bodega; aquí se gestiona la última milla.</p></div><div className="tms-list-tools"><label className="storage-search"><input placeholder="Buscar viaje, ruta, placa o conductor" value={search} onChange={(e)=>setSearch(e.target.value)}/></label><select value={filter} onChange={(e)=>setFilter(e.target.value)}><option value="all">Todos los estados</option>{Object.entries(tripStatuses).map(([key,value])=><option key={key} value={key}>{value}</option>)}</select></div></div>
      {filteredTrips.length===0?<div className="tms-empty"><Route size={31}/><strong>No hay viajes planificados</strong><span>Despacha los pedidos en Preparación y despacho y luego crea una ruta.</span></div>:<div className="storage-table-wrap"><table className="tms-table"><thead><tr><th>Viaje / ruta</th><th>Transportista / vehículo</th><th>Conductor</th><th>Salida planificada</th><th>Paradas</th><th>Costo / factura</th><th>Estado</th><th></th></tr></thead><tbody>{filteredTrips.map((trip)=><tr key={trip.id}><td><strong>{trip.trip_number}</strong><small>{trip.route_name}{trip.zone?` · ${trip.zone}`:''}</small></td><td>{trip.carrier_name||'—'}<small>{trip.vehicle_plate||'Sin placa'} · {trip.vehicle_type||''}</small></td><td>{trip.driver_name||'—'}</td><td>{new Date(trip.planned_departure).toLocaleString('es-EC')}<small>{trip.planned_distance_km} km · {trip.planned_duration_minutes} min</small></td><td>{trip.completed_stops}/{trip.stop_count}<small>{trip.open_incidents} incidencias</small></td><td>${Number(trip.estimated_cost).toFixed(2)}<small>{trip.reconciliation_status==='variance'?'Diferencia de factura':trip.reconciliation_status==='matched'?'Conciliada':'Pendiente de factura'}</small></td><td><span className={`tms-status ${trip.status}`}>{tripStatuses[trip.status]}</span></td><td><button className="storage-text-button" onClick={()=>void openTrip(trip.id)}>Abrir <ArrowRight size={14}/></button></td></tr>)}</tbody></table></div>}
    </section>}

    {activeTrip&&tab==='trips'&&<section className="storage-panel tms-trip-detail"><div className="tms-detail-heading"><div><span className="tms-trip-code">{activeTrip.trip_number} · MAN-{activeTrip.trip_number}</span><h2>{activeTrip.route_name}</h2><p><Truck size={14}/> {activeTrip.carrier_name} · {activeTrip.vehicle_plate} · {activeTrip.driver_name} · {activeTrip.zone||'Sin zona definida'}</p></div><div className="tms-detail-actions"><span className={`tms-status ${activeTrip.status}`}>{tripStatuses[activeTrip.status]}</span><button className="storage-icon-button" onClick={()=>window.print()} aria-label="Imprimir manifiesto"><Printer size={16}/></button><button className="storage-icon-button" onClick={()=>setActiveTrip(null)} aria-label="Cerrar detalle"><X size={16}/></button></div></div>
      <div className="tms-trip-stats"><div><span>Distancia estimada</span><strong>{Number(activeTrip.planned_distance_km).toFixed(1)} km</strong></div><div><span>Duración estimada</span><strong>{activeTrip.planned_duration_minutes} min</strong></div><div><span>Tarifa estimada</span><strong>${Number(activeTrip.estimated_cost).toFixed(2)}</strong></div><div><span>Gastos liquidados</span><strong>${Number(activeTrip.actual_cost||activeTrip.expenses.reduce((sum:number,item:Row)=>sum+Number(item.amount),0)).toFixed(2)}</strong></div></div>
      {activeTrip.status==='planned'&&canDispatch&&<div className="tms-depart-banner"><div><strong>Verificación de salida</strong><small>Matrícula, seguro y licencia deben estar vigentes. Los pedidos ya deben constar como despachados en el módulo D.</small></div><button className="action-btn" disabled={busy} onClick={()=>void depart()}><Truck size={15}/> Iniciar viaje</button></div>}
      {activeTrip.status==='in_route'&&<div className="tms-route-live"><span><span className="tms-live-dot"/> Viaje activo</span><small>Salió {activeTrip.departed_at?new Date(activeTrip.departed_at).toLocaleString('es-EC'):'—'} · seguimiento manual desde este panel</small></div>}
      <div className="tms-stop-list"><div className="tms-section-title"><div><h3><MapPin size={17}/> Paradas y prueba de entrega</h3><p>La secuencia y las ventanas horarias se pueden ajustar antes de salir.</p></div><span>{activeTrip.stops.length} paradas</span></div>
        {activeTrip.stops.map((stop:Row,index:number)=>{const form=stopForms[stop.id]||{};return <article className="tms-stop-card" key={stop.id}><div className="tms-stop-marker"><span>{stop.sequence_number}</span></div><div className="tms-stop-main"><div className="tms-stop-heading"><div><strong>{stop.stop_name||stop.recipient_name||'Destinatario'}</strong><small>{stop.fulfillment_number} · {stop.sale_number} · {stop.city||'Ciudad por confirmar'}</small><small>{stop.address||'Sin dirección de entrega'}</small></div><span className={`tms-stop-status ${stop.status}`}>{stopStatuses[stop.status]}</span></div>
          <div className="tms-stop-window"><label>Desde<input type="datetime-local" value={form.scheduled_from||''} disabled={activeTrip.status!=='planned'||!canManage} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,scheduled_from:e.target.value}})}/></label><label>Hasta<input type="datetime-local" value={form.scheduled_to||''} disabled={activeTrip.status!=='planned'||!canManage} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,scheduled_to:e.target.value}})}/></label>{activeTrip.status==='planned'&&<div className="tms-sequence-buttons"><button type="button" className="tms-save-window" disabled={!canManage||busy} onClick={()=>void saveWindow(stop)} title="Guardar ventana horaria"><Check size={13}/></button><button type="button" title="Subir parada" disabled={index===0||!canManage} onClick={()=>void moveStop(stop.id,-1)}><ArrowUpDown size={14}/></button><button type="button" title="Bajar parada" disabled={index===activeTrip.stops.length-1||!canManage} onClick={()=>void moveStop(stop.id,1)}><ArrowUpDown size={14}/></button></div>}</div>
          <div className="tms-stop-items">{stop.items.map((item:Row)=><div key={item.fulfillment_item_id}><span><strong>{item.product_name}</strong><small>{item.sku} · Lote {item.batch_number}</small></span><span>{item.delivered_quantity}/{item.expected_quantity} entregadas</span>{activeTrip.status==='in_route'&&stop.status!=='delivered'&&stop.status!=='partial'&&stop.status!=='failed'&&stop.status!=='rescheduled'&&<label>Entregar<input type="number" min="0" max={Number(item.expected_quantity)-Number(item.delivered_quantity)} value={form.items?.[item.fulfillment_item_id]??''} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,items:{...form.items,[item.fulfillment_item_id]:e.target.value}}})}/></label>}</div>)}</div>
          {activeTrip.status==='in_route'&&canDeliver&&['planned','arrived'].includes(stop.status)&&<form className="tms-pod-form" onSubmit={(e)=>void updateStop(e,stop)}><div className="tms-pod-grid"><label>Estado<select value={form.status} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,status:e.target.value}})}><option value="delivered">Entregado completo</option><option value="partial">Entrega parcial</option><option value="failed">Entrega fallida</option><option value="rescheduled">Reprogramar</option></select></label><label>Recibió<input value={form.received_by} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,received_by:e.target.value}})} placeholder="Nombre del receptor"/></label><label>Firma / referencia<input value={form.signature_reference} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,signature_reference:e.target.value}})} placeholder="URL o código de firma"/></label><label>Foto / referencia<input value={form.photo_reference} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,photo_reference:e.target.value}})} placeholder="URL o código de foto"/></label>{form.status==='failed'&&<label>Motivo de fallo<input value={form.failure_reason} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,failure_reason:e.target.value}})} required/></label>}{form.status==='rescheduled'&&<label>Nueva fecha<input type="datetime-local" value={form.rescheduled_for} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,rescheduled_for:e.target.value}})} required/></label>}<label>Latitud (opcional)<input type="number" step="any" value={form.latitude} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,latitude:e.target.value}})}/></label><label>Longitud (opcional)<input type="number" step="any" value={form.longitude} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,longitude:e.target.value}})}/></label><label className="wide">Notas de entrega<input value={form.delivery_notes} onChange={(e)=>setStopForms({...stopForms,[stop.id]:{...form,delivery_notes:e.target.value}})} placeholder="Observaciones, recepción parcial o estado del paquete"/></label></div><div className="tms-pod-actions">{stop.status==='planned'&&<button type="button" className="tms-outline-button" onClick={()=>void apiAction(`/api/tms/trips/${activeTrip.id}/stops/${stop.id}/status`,'POST',{status:'arrived'})}><MapPin size={14}/> Registrar llegada</button>}<button className="action-btn" disabled={busy}><BadgeCheck size={14}/> Guardar resultado / POD</button></div></form>}
          {stop.status!=='planned'&&stop.status!=='arrived'&&<div className="tms-pod-summary"><CheckCircle2 size={15}/><span>{stop.received_by?`Recibió: ${stop.received_by}`:''}{stop.delivery_notes?` · ${stop.delivery_notes}`:''}{stop.failure_reason?` · Motivo: ${stop.failure_reason}`:''}{stop.rescheduled_for?` · Nueva fecha: ${new Date(stop.rescheduled_for).toLocaleString('es-EC')}`:''}</span>{stop.signature_reference&&<a href={stop.signature_reference} target="_blank" rel="noreferrer">Firma / POD</a>}{stop.photo_reference&&<a href={stop.photo_reference} target="_blank" rel="noreferrer">Foto</a>}</div>}
        </div></article>;})}
      </div>
      <div className="tms-lower-grid"><section className="tms-subpanel"><div className="tms-section-title"><div><h3><CircleDollarSign size={17}/> Gastos del viaje</h3><p>Combustible, peajes, parqueos y viáticos.</p></div></div>{activeTrip.status!=='closed'&&canFinance&&<form className="tms-inline-form" onSubmit={addExpense}><select value={expenseForm.expense_type} onChange={(e)=>setExpenseForm({...expenseForm,expense_type:e.target.value})}>{Object.entries(expenseNames).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><input value={expenseForm.description} onChange={(e)=>setExpenseForm({...expenseForm,description:e.target.value})} placeholder="Detalle / comprobante" required/><input type="number" min="0" step="0.01" value={expenseForm.amount} onChange={(e)=>setExpenseForm({...expenseForm,amount:e.target.value})} placeholder="$" required/><button className="tms-icon-submit" disabled={busy} aria-label="Agregar gasto"><Plus size={16}/></button></form>}<div className="tms-expense-list">{activeTrip.expenses.map((expense:Row)=><article key={expense.id}><span><Fuel size={15}/><strong>{expenseNames[expense.expense_type]} · {expense.description}</strong><small>{expense.receipt_reference||'Sin referencia'} · {new Date(expense.created_at).toLocaleString('es-EC')}</small></span><b>${Number(expense.amount).toFixed(2)}</b></article>)}{activeTrip.expenses.length===0&&<small className="tms-muted">Sin gastos registrados.</small>}</div></section>
        <section className="tms-subpanel"><div className="tms-section-title"><div><h3><AlertTriangle size={17}/> Incidentes y siniestros</h3><p>Registra novedades y enlaza reclamaciones.</p></div></div>{activeTrip.status!=='closed'&&canIncidents&&<form className="tms-incident-form" onSubmit={addIncident}><select value={incidentForm.incident_type} onChange={(e)=>setIncidentForm({...incidentForm,incident_type:e.target.value})}>{Object.entries(incidentNames).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><select value={incidentForm.severity} onChange={(e)=>setIncidentForm({...incidentForm,severity:e.target.value})}><option value="low">Baja</option><option value="medium">Media</option><option value="high">Alta</option><option value="critical">Crítica</option></select><input className="wide" value={incidentForm.description} onChange={(e)=>setIncidentForm({...incidentForm,description:e.target.value})} placeholder="Describe el incidente" required/><input value={incidentForm.claim_reference} onChange={(e)=>setIncidentForm({...incidentForm,claim_reference:e.target.value})} placeholder="Ref. siniestro / reclamo"/><input type="number" min="0" step="0.01" value={incidentForm.estimated_loss} onChange={(e)=>setIncidentForm({...incidentForm,estimated_loss:Number(e.target.value)})} placeholder="Pérdida estimada $"/><button className="tms-outline-button"><Plus size={14}/> Registrar incidente</button></form>}<div className="tms-incident-list">{activeTrip.incidents.map((incident:Row)=><article key={incident.id}><span><strong>{incidentNames[incident.incident_type]} · {incident.severity.toUpperCase()}</strong><small>{incident.description} · {incident.claim_reference||'Sin reclamo'} · ${Number(incident.estimated_loss).toFixed(2)}</small></span><span className={`tms-incident-status ${incident.status}`}>{incident.status==='resolved'?'Resuelto':incident.status==='claim'?'En reclamo':'Abierto'}</span></article>)}{activeTrip.incidents.length===0&&<small className="tms-muted">Sin incidentes registrados.</small>}</div></section></div>
      <section className="tms-subpanel tms-invoice-panel"><div className="tms-section-title"><div><h3><FileText size={17}/> Liquidación y factura del transportista</h3><p>Tarifa estimada comparada con factura; los gastos operativos se liquidan por separado.</p></div><span className={`tms-reconciliation ${activeTrip.reconciliation_status}`}>{activeTrip.reconciliation_status==='matched'?'Conciliada':activeTrip.reconciliation_status==='variance'?'Con diferencia':'Pendiente'}</span></div><div className="tms-invoice-values"><div><span>Tarifa calculada</span><strong>${Number(activeTrip.estimated_cost).toFixed(2)}</strong></div><div><span>Gastos de viaje</span><strong>${Number(activeTrip.actual_cost||activeTrip.expenses.reduce((sum:number,item:Row)=>sum+Number(item.amount),0)).toFixed(2)}</strong></div><div><span>Factura transportista</span><strong>${Number(activeTrip.invoiced_amount||0).toFixed(2)}</strong></div><div><span>Referencia</span><strong>{activeTrip.invoice_reference||'Sin factura'}</strong></div></div>{activeTrip.status==='in_route'&&canDispatch&&<button className="action-btn" onClick={()=>setShowClose(true)}><Check size={15}/> Cerrar viaje y conciliar</button>}{activeTrip.status==='closed'&&<p className="tms-reconciliation-note">Variación factura vs tarifa: <strong>${(Number(activeTrip.invoiced_amount)-Number(activeTrip.estimated_cost)).toFixed(2)}</strong> · costo operativo registrado: <strong>${Number(activeTrip.actual_cost).toFixed(2)}</strong></p>}</section>
      <section className="tms-subpanel tms-timeline"><div className="tms-section-title"><div><h3><Clock3 size={17}/> Historial del viaje</h3><p>Salida, paradas, POD, gastos e incidentes.</p></div></div>{activeTrip.events.map((event:Row)=><article key={event.id}><span className="tms-event-icon"><Clock3 size={14}/></span><div><strong>{event.event_type}</strong><small>{new Date(event.created_at).toLocaleString('es-EC')} · {event.created_by_name||'Sistema'}{event.notes?` · ${event.notes}`:''}</small></div></article>)}</section>
      <div className="tms-manifest-print"><header><strong>MANIFIESTO DE CARGA</strong><span>{activeTrip.trip_number} · MAN-{activeTrip.trip_number}</span></header><p>Transportista: {activeTrip.carrier_name} · Vehículo: {activeTrip.vehicle_plate} · Conductor: {activeTrip.driver_name} · Licencia: {activeTrip.license_number}</p><p>Ruta: {activeTrip.route_name} · Zona: {activeTrip.zone||'—'} · Salida: {new Date(activeTrip.planned_departure).toLocaleString('es-EC')}</p>{activeTrip.manifest.map((entry:Row,index:number)=><article key={entry.fulfillment_order_id}><b>{index+1}. {entry.fulfillment_number} · {entry.sale_number}</b><span>{entry.recipient_name} · {entry.shipping_city}</span><span>{entry.shipping_address}</span></article>)}</div>
    </section>}

    {tab==='resources'&&<div className="tms-resource-grid">
      <section className="storage-panel"><div className="storage-panel-heading"><div><h2><Truck size={18}/> Transportistas y mensajería</h2><p>Propios, tercerizados y zonas de servicio.</p></div></div>{canManage&&<form className="tms-resource-form" onSubmit={(e)=>void saveResource(e,'/api/tms/carriers',carrierForm,setCarrierForm,{name:'',carrier_type:'transport_company',tax_id:'',contact_name:'',phone:'',email:'',zones:''})}><input value={carrierForm.name} onChange={(e)=>setCarrierForm({...carrierForm,name:e.target.value})} placeholder="Razón social / transportista" required/><select value={carrierForm.carrier_type} onChange={(e)=>setCarrierForm({...carrierForm,carrier_type:e.target.value})}><option value="transport_company">Transportista</option><option value="courier">Mensajería</option><option value="own">Flota propia</option></select><input value={carrierForm.tax_id} onChange={(e)=>setCarrierForm({...carrierForm,tax_id:e.target.value})} placeholder="RUC / identificación"/><input value={carrierForm.contact_name} onChange={(e)=>setCarrierForm({...carrierForm,contact_name:e.target.value})} placeholder="Contacto"/><input value={carrierForm.phone} onChange={(e)=>setCarrierForm({...carrierForm,phone:e.target.value})} placeholder="Teléfono"/><input value={carrierForm.email} onChange={(e)=>setCarrierForm({...carrierForm,email:e.target.value})} placeholder="Correo"/><input className="wide" value={carrierForm.zones} onChange={(e)=>setCarrierForm({...carrierForm,zones:e.target.value})} placeholder="Zonas de cobertura separadas por coma"/><button className="action-btn"><Plus size={14}/> Registrar</button></form>}<div className="tms-resource-list">{context.carriers.map((carrier:Row)=><article key={carrier.id}><span><strong>{carrier.name}</strong><small>{carrier.carrier_type==='courier'?'Mensajería':carrier.carrier_type==='own'?'Flota propia':'Transportista'} · {carrier.tax_id||'Sin identificación'} · {carrier.phone||carrier.email||'Sin contacto'}</small></span><div className="tms-resource-actions"><span className={carrier.is_active?'resource-active':'resource-inactive'}>{carrier.is_active?'Activo':'Inactivo'}</span>{canManage&&<button type="button" onClick={()=>toggleResource('carriers',carrier)}>{carrier.is_active?'Desactivar':'Activar'}</button>}</div></article>)}</div></section>
      <section className="storage-panel"><div className="storage-panel-heading"><div><h2><Truck size={18}/> Flota, capacidad y documentación</h2><p>Matrícula y póliza deben estar vigentes para salir.</p></div></div>{canManage&&<form className="tms-resource-form" onSubmit={(e)=>void saveResource(e,'/api/tms/vehicles',vehicleForm,setVehicleForm,{carrier_id:'',plate:'',vehicle_type:'camioneta',is_owned:false,capacity_kg:0,capacity_m3:0,capacity_packages:0,registration_expiry:'',insurance_expiry:''})}><select value={vehicleForm.carrier_id} onChange={(e)=>setVehicleForm({...vehicleForm,carrier_id:e.target.value})}><option value="">Vehículo propio (sin transportista)</option>{context.carriers.map((carrier:Row)=><option key={carrier.id} value={carrier.id}>{carrier.name}</option>)}</select><input value={vehicleForm.plate} onChange={(e)=>setVehicleForm({...vehicleForm,plate:e.target.value.toUpperCase()})} placeholder="Placa" required/><input value={vehicleForm.vehicle_type} onChange={(e)=>setVehicleForm({...vehicleForm,vehicle_type:e.target.value})} placeholder="Tipo (camión, furgón...)" required/><input type="number" min="0" value={vehicleForm.capacity_kg} onChange={(e)=>setVehicleForm({...vehicleForm,capacity_kg:Number(e.target.value)})} placeholder="Capacidad kg"/><input type="number" min="0" step=".1" value={vehicleForm.capacity_m3} onChange={(e)=>setVehicleForm({...vehicleForm,capacity_m3:Number(e.target.value)})} placeholder="Capacidad m³"/><input type="number" min="0" value={vehicleForm.capacity_packages} onChange={(e)=>setVehicleForm({...vehicleForm,capacity_packages:Number(e.target.value)})} placeholder="N.º paquetes"/><label>Matrícula hasta<input type="date" value={vehicleForm.registration_expiry} onChange={(e)=>setVehicleForm({...vehicleForm,registration_expiry:e.target.value})}/></label><label>Seguro hasta<input type="date" value={vehicleForm.insurance_expiry} onChange={(e)=>setVehicleForm({...vehicleForm,insurance_expiry:e.target.value})}/></label><label className="tms-owned-toggle"><input type="checkbox" checked={vehicleForm.is_owned} onChange={(e)=>setVehicleForm({...vehicleForm,is_owned:e.target.checked})}/> Flota propia</label><button className="action-btn"><Plus size={14}/> Registrar vehículo</button></form>}<div className="tms-resource-list">{context.vehicles.map((vehicle:Row)=><article key={vehicle.id}><span><strong>{vehicle.plate} · {vehicle.vehicle_type}</strong><small>{vehicle.carrier_name||'Flota propia'} · {vehicle.capacity_kg||'—'} kg · {vehicle.capacity_m3||'—'} m³ · {vehicle.capacity_packages||'—'} bultos</small></span><div className="tms-resource-actions"><span className={vehicle.registration_expired||vehicle.insurance_expired?'resource-expired':vehicle.status==='active'?'resource-active':'resource-inactive'}>{vehicle.registration_expired||vehicle.insurance_expired?'Documento vencido':vehicle.status==='active'?'Disponible':vehicle.status}</span>{canManage&&<button type="button" onClick={()=>toggleResource('vehicles',vehicle)}>{vehicle.status==='active'?'Desactivar':'Activar'}</button>}</div></article>)}</div></section>
      <section className="storage-panel"><div className="storage-panel-heading"><div><h2><UserRound size={18}/> Conductores y licencias</h2><p>Control de licencia vigente y asignación al proveedor.</p></div></div>{canManage&&<form className="tms-resource-form" onSubmit={(e)=>void saveResource(e,'/api/tms/drivers',driverForm,setDriverForm,{carrier_id:'',full_name:'',identification_number:'',phone:'',license_number:'',license_type:'',license_expiry:''})}><select value={driverForm.carrier_id} onChange={(e)=>setDriverForm({...driverForm,carrier_id:e.target.value})}><option value="">Conductor de flota propia</option>{context.carriers.map((carrier:Row)=><option key={carrier.id} value={carrier.id}>{carrier.name}</option>)}</select><input value={driverForm.full_name} onChange={(e)=>setDriverForm({...driverForm,full_name:e.target.value})} placeholder="Nombre completo" required/><input value={driverForm.identification_number} onChange={(e)=>setDriverForm({...driverForm,identification_number:e.target.value})} placeholder="Cédula"/><input value={driverForm.phone} onChange={(e)=>setDriverForm({...driverForm,phone:e.target.value})} placeholder="Teléfono"/><input value={driverForm.license_number} onChange={(e)=>setDriverForm({...driverForm,license_number:e.target.value})} placeholder="Número de licencia" required/><input value={driverForm.license_type} onChange={(e)=>setDriverForm({...driverForm,license_type:e.target.value})} placeholder="Tipo de licencia"/><label className="wide">Vigencia licencia<input type="date" value={driverForm.license_expiry} onChange={(e)=>setDriverForm({...driverForm,license_expiry:e.target.value})} required/></label><button className="action-btn"><Plus size={14}/> Registrar conductor</button></form>}<div className="tms-resource-list">{context.drivers.map((driver:Row)=><article key={driver.id}><span><strong>{driver.full_name}</strong><small>{driver.carrier_name||'Flota propia'} · Lic. {driver.license_number} ({driver.license_type||'Tipo pendiente'}) · vence {new Date(driver.license_expiry).toLocaleDateString('es-EC')}</small></span><span className={driver.license_expired?'resource-expired':'resource-active'}>{driver.license_expired?'Licencia vencida':driver.status==='active'?'Activo':'Inactivo'}</span></article>)}</div></section>
      <section className="storage-panel"><div className="storage-panel-heading"><div><h2><CircleDollarSign size={18}/> Tarifas por zona y carga</h2><p>Base + distancia + peso + volumen + bultos + paradas.</p></div></div>{canManage&&<form className="tms-resource-form tms-tariff-form" onSubmit={(e)=>void saveResource(e,'/api/tms/tariffs',tariffForm,setTariffForm,{carrier_id:'',name:'',zone:'',base_amount:0,per_km:0,per_kg:0,per_m3:0,per_package:0,per_stop:0,minimum_amount:0})}><select value={tariffForm.carrier_id} onChange={(e)=>setTariffForm({...tariffForm,carrier_id:e.target.value})}><option value="">Tarifa general</option>{context.carriers.map((carrier:Row)=><option key={carrier.id} value={carrier.id}>{carrier.name}</option>)}</select><input value={tariffForm.name} onChange={(e)=>setTariffForm({...tariffForm,name:e.target.value})} placeholder="Nombre de tarifa" required/><input className="wide" value={tariffForm.zone} onChange={(e)=>setTariffForm({...tariffForm,zone:e.target.value})} placeholder="Zona / ciudad (vacío = todas)"/>{[['base_amount','Base $'],['per_km','Por km $'],['per_kg','Por kg $'],['per_m3','Por m³ $'],['per_package','Por paquete $'],['per_stop','Por parada $'],['minimum_amount','Mínimo $']].map(([key,label])=><label key={key}>{label}<input type="number" min="0" step=".01" value={tariffForm[key]} onChange={(e)=>setTariffForm({...tariffForm,[key]:Number(e.target.value)})}/></label>)}<button className="action-btn"><Plus size={14}/> Guardar tarifa</button></form>}<div className="tms-resource-list">{context.tariffs.map((tariff:Row)=><article key={tariff.id}><span><strong>{tariff.name} · {tariff.zone||'Todas las zonas'}</strong><small>{tariff.carrier_name||'General'} · base ${Number(tariff.base_amount).toFixed(2)} + ${Number(tariff.per_km).toFixed(2)}/km + ${Number(tariff.per_package).toFixed(2)}/bulto + ${Number(tariff.per_stop).toFixed(2)}/parada</small></span><span className={tariff.is_active?'resource-active':'resource-inactive'}>{tariff.is_active?'Activa':'Inactiva'}</span></article>)}</div></section>
    </div>}

    {tab==='incidents'&&<section className="storage-panel"><div className="storage-panel-heading"><div><h2><AlertTriangle size={19}/> Incidentes y siniestros</h2><p>Demoras, daños, robos, accidentes y reclamos vinculados a viajes.</p></div><button className="storage-icon-button" onClick={()=>void refresh()} aria-label="Actualizar incidentes"><RefreshCw size={16}/></button></div>{context.incidents.length===0?<div className="tms-empty"><ShieldAlert size={30}/><strong>Sin incidentes abiertos</strong><span>Las novedades ingresadas desde cada viaje aparecerán aquí.</span></div>:<div className="storage-table-wrap"><table className="tms-table"><thead><tr><th>Fecha / gravedad</th><th>Tipo / viaje</th><th>Descripción</th><th>Reclamo / pérdida</th><th>Estado</th><th></th></tr></thead><tbody>{context.incidents.map((incident:Row)=><tr key={incident.id}><td>{new Date(incident.occurred_at).toLocaleString('es-EC')}<small>{incident.severity.toUpperCase()}</small></td><td>{incidentNames[incident.incident_type]}<small>{incident.trip_number}</small></td><td>{incident.description}</td><td>{incident.claim_reference||'—'}<small>${Number(incident.estimated_loss).toFixed(2)}</small></td><td><span className={`tms-incident-status ${incident.status}`}>{incident.status==='claim'?'En reclamo':incident.status==='resolved'?'Resuelto':'Abierto'}</span></td><td>{canIncidents&&incident.status!=='resolved'&&<div className="tms-incident-actions"><button onClick={()=>void resolveIncident(incident.id,'claim')}>Reclamo</button><button onClick={()=>void resolveIncident(incident.id,'resolved')}>Resolver</button></div>}</td></tr>)}</tbody></table></div>}</section>}

    {showCreate&&<div className="storage-modal-backdrop tms-modal-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)setShowCreate(false)}}><form className="storage-modal tms-create-modal" onSubmit={createTrip}><div className="storage-panel-heading"><div><p className="eyebrow">PLANIFICACIÓN MANUAL DE RUTA</p><h2>Crear viaje de distribución</h2><p>Selecciona pedidos que ya salieron de bodega. La ruta y distancia son estimadas por el operador.</p></div><button type="button" className="storage-icon-button" onClick={()=>setShowCreate(false)} aria-label="Cerrar"><X size={16}/></button></div>
      <div className="tms-create-grid"><label>Transportista<select required value={tripForm.carrier_id} onChange={(e)=>setTripForm({...tripForm,carrier_id:e.target.value,vehicle_id:'',driver_id:'',tariff_id:''})}><option value="">Selecciona…</option>{context.carriers.filter((carrier:Row)=>carrier.is_active).map((carrier:Row)=><option key={carrier.id} value={carrier.id}>{carrier.name} · {carrier.carrier_type==='own'?'Flota propia':carrier.carrier_type==='courier'?'Mensajería':'Tercerizado'}</option>)}</select></label><label>Vehículo<select required value={tripForm.vehicle_id} onChange={(e)=>setTripForm({...tripForm,vehicle_id:e.target.value})}><option value="">Selecciona…</option>{compatibleVehicles.map((vehicle:Row)=><option key={vehicle.id} value={vehicle.id}>{vehicle.plate} · {vehicle.vehicle_type} · {vehicle.capacity_kg||'∞'} kg</option>)}</select></label><label>Conductor<select required value={tripForm.driver_id} onChange={(e)=>setTripForm({...tripForm,driver_id:e.target.value})}><option value="">Selecciona…</option>{compatibleDrivers.map((driver:Row)=><option key={driver.id} value={driver.id}>{driver.full_name} · lic. {driver.license_number}{driver.license_expired?' · VENCIDA':''}</option>)}</select></label><label>Nombre de ruta<input required value={tripForm.route_name} onChange={(e)=>setTripForm({...tripForm,route_name:e.target.value})} placeholder="Ruta norte, Cuenca centro…"/></label><label>Zona / ciudad<input value={tripForm.zone} onChange={(e)=>setTripForm({...tripForm,zone:e.target.value})} placeholder="Quito norte, Guayaquil…"/></label><label>Salida estimada<input type="datetime-local" required value={tripForm.planned_departure} onChange={(e)=>setTripForm({...tripForm,planned_departure:e.target.value})}/></label><label>Retorno estimado<input type="datetime-local" value={tripForm.planned_return} onChange={(e)=>setTripForm({...tripForm,planned_return:e.target.value})}/></label><label>Distancia estimada (km)<input type="number" min="0" step=".1" value={tripForm.planned_distance_km} onChange={(e)=>setTripForm({...tripForm,planned_distance_km:Number(e.target.value)})}/></label><label>Duración estimada (min)<input type="number" min="0" step="1" value={tripForm.planned_duration_minutes} onChange={(e)=>setTripForm({...tripForm,planned_duration_minutes:Number(e.target.value)})}/></label><label>Tarifa del proveedor<select value={tripForm.tariff_id} onChange={(e)=>setTripForm({...tripForm,tariff_id:e.target.value})}><option value="">Sin tarifa · costo manual</option>{context.tariffs.filter((tariff:Row)=>tariff.is_active&&(!tariff.carrier_id||tariff.carrier_id===tripForm.carrier_id)&&(!tariff.zone||!tripForm.zone||tariff.zone.toLowerCase()===tripForm.zone.toLowerCase())).map((tariff:Row)=><option key={tariff.id} value={tariff.id}>{tariff.name} · {tariff.zone||'General'}</option>)}</select></label>{!chosenTariff&&<label>Costo estimado manual ($)<input type="number" min="0" step=".01" value={tripForm.estimated_cost} onChange={(e)=>setTripForm({...tripForm,estimated_cost:Number(e.target.value)})}/></label>}<label className="wide">Notas de viaje<input value={tripForm.notes} onChange={(e)=>setTripForm({...tripForm,notes:e.target.value})} placeholder="Instrucciones de ruta, ventanas, peajes previstos"/></label></div>
      <div className="tms-capacity-preview"><span>{selectedOrders.length} paradas</span><span>{estimatedWeight.toFixed(1)} kg</span><span>{estimatedVolume.toFixed(2)} m³</span><span>{estimatedPackages} paquetes</span><strong>Tarifa estimada: ${Number(tariffEstimate??tripForm.estimated_cost).toFixed(2)}</strong></div>
      <div className="tms-order-picker"><div className="tms-section-title"><div><h3>Pedidos listos para distribución</h3><p>Pedidos con salida física confirmada; selecciona y ordena las paradas.</p></div></div>{context.orders.length===0?<div className="tms-empty compact">No hay pedidos despachados con unidades pendientes de entrega.</div>:<div className="tms-order-picker-list">{context.orders.map((order:Row)=>{const selected=orderIds.includes(order.id);return <article key={order.id} className={selected?'selected':''}><input type="checkbox" checked={selected} onChange={(e)=>toggleOrder(order.id,e.target.checked)}/><span><strong>{order.fulfillment_number} · {order.recipient_name||'Destinatario'}</strong><small>{order.sale_number} · {order.shipping_city||'Sin ciudad'} · {order.pending_delivery_units} u. pendientes · {order.package_count} bultos</small><small>{order.shipping_address||'Sin dirección'}</small></span>{selected&&<div className="tms-stop-order-controls"><button type="button" disabled={orderIds.indexOf(order.id)===0} onClick={()=>setOrderIds((current)=>{const next=[...current];const i=next.indexOf(order.id);[next[i-1],next[i]]=[next[i],next[i-1]];return next;})} title="Subir parada">↑</button><button type="button" disabled={orderIds.indexOf(order.id)===orderIds.length-1} onClick={()=>setOrderIds((current)=>{const next=[...current];const i=next.indexOf(order.id);[next[i+1],next[i]]=[next[i],next[i+1]];return next;})} title="Bajar parada">↓</button><small>Parada {orderIds.indexOf(order.id)+1}</small></div>}</article>;})}</div>}</div>
      {orderIds.length>0&&<div className="tms-stop-window-editor"><strong>Ventanas horarias (opcionales)</strong>{selectedOrders.map((order:Row)=><div key={order.id}><span>{orderIds.indexOf(order.id)+1}. {order.recipient_name||order.fulfillment_number} · {order.shipping_city}</span><input aria-label="Desde" type="datetime-local" value={stopWindows[order.id]?.from||''} onChange={(e)=>setStopWindows({...stopWindows,[order.id]:{...stopWindows[order.id],from:e.target.value}})}/><input aria-label="Hasta" type="datetime-local" value={stopWindows[order.id]?.to||''} onChange={(e)=>setStopWindows({...stopWindows,[order.id]:{...stopWindows[order.id],to:e.target.value}})}/></div>)}</div>}
      <div className="tms-create-actions"><button type="button" className="storage-text-button" onClick={()=>setShowCreate(false)}>Cancelar</button><button className="action-btn" disabled={busy||!canManage||!orderIds.length}><Route size={15}/> Crear ruta y manifiesto</button></div>
    </form></div>}

    {showClose&&activeTrip&&<div className="storage-modal-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)setShowClose(false)}}><form className="storage-modal tms-close-modal" onSubmit={closeTrip}><div className="storage-panel-heading"><div><h2>Cerrar viaje y conciliar factura</h2><p>Los gastos cargados se consolidan; compara la factura del transportista contra la tarifa.</p></div><button type="button" className="storage-icon-button" onClick={()=>setShowClose(false)} aria-label="Cerrar"><X size={16}/></button></div><div className="tms-close-summary"><span>Tarifa estimada<strong>${Number(activeTrip.estimated_cost).toFixed(2)}</strong></span><span>Gastos de ruta<strong>${Number(activeTrip.expenses.reduce((sum:number,item:Row)=>sum+Number(item.amount),0)).toFixed(2)}</strong></span></div><div className="tms-create-grid"><label>Total de factura ($)<input type="number" min="0" step=".01" value={closeForm.invoiced_amount} onChange={(e)=>setCloseForm({...closeForm,invoiced_amount:e.target.value})}/></label><label>Referencia de factura<input value={closeForm.invoice_reference} onChange={(e)=>setCloseForm({...closeForm,invoice_reference:e.target.value})} placeholder="RUC / número de factura"/></label></div><div className="tms-create-actions"><button type="button" className="storage-text-button" onClick={()=>setShowClose(false)}>Volver</button><button className="action-btn" disabled={busy}><Check size={15}/> Cerrar y conciliar</button></div></form></div>}
    <p className="tms-footnote">La distancia y duración se planifican manualmente; el costo se estima con tarifas configuradas. El TMS no depende de una licencia de mapas. Firma y fotografías se registran como referencias o enlaces; la geolocalización es opcional.</p>
  </div></main></div>;
}
